# Pulumi ComponentResource: S3 + RDS + IAM

## Project Structure

```
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── Pulumi.yaml
├── package.json
├── tsconfig.json
└── src/
    ├── index.ts          # Entry point
    ├── datastore.ts      # ComponentResource
    └── types.ts          # Shared types
```

## Stack Configs

**`Pulumi.yaml`**
```yaml
name: app-infra
runtime: nodejs
description: Application data layer (S3, RDS, IAM)
```

**`Pulumi.dev.yaml`**
```yaml
config:
  app:region: us-east-1
  app:environment: dev
  app:rdsInstanceClass: db.t3.micro
  app:rdsAllocatedStorage: 20
  app:rdsMultiAz: "false"
  app:rdsStorageEncrypted: "false"
  app:dbPassword:
    secure: AAAB...  # pulumi config pass app:dbPassword --plaintext '...'
  app:sseAlgorithm: AES256
```

**`Pulumi.prod.yaml`**
```yaml
config:
  app:region: us-east-1
  app:environment: prod
  app:rdsInstanceClass: db.t3.medium
  app:rdsAllocatedStorage: 100
  app:rdsMultiAz: "true"
  app:rdsStorageEncrypted: "true"
  app:dbPassword:
    secure: AAAB...  # pulumi config pass app:dbPassword --plaintext '...'
  app:sseAlgorithm: aws:kms
  app:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/XXXX
```

## Source

**`src/types.ts`**
```typescript
import * as pulumi from "@pulumi/pulumi";

/**
 * Configuration passed into the Datastore component.
 * Derived from stack config so each stack is independently deployable.
 */
export interface DatastoreArgs {
    /** AWS region for all resources. */
    region: string;
    /** Logical environment name: "dev" | "prod". */
    environment: string;
    /** RDS instance class (e.g., "db.t3.micro"). */
    rdsInstanceClass: string;
    /** Allocated storage in GiB. */
    rdsAllocatedStorage: number;
    /** Enable multi-AZ deployment. */
    rdsMultiAz: boolean;
    /** Enable RDS storage encryption. */
    rdsStorageEncrypted: boolean;
    /** S3 server-side encryption algorithm: "AES256" | "aws:kms". */
    sseAlgorithm: string;
    /** KMS key ARN (required when sseAlgorithm is "aws:kms"). */
    kmsKeyArn?: string;
    /** Encrypted database password (pulumi config pass). */
    dbPassword: pulumi.Input<string>;
    /** OIDC provider ARN for IRSA trust (prod only). */
    oidcProviderArn?: string;
    /** OIDC service account name (prod only). */
    oidcServiceAccount?: string;
}

/**
 * Outputs exposed by the Datastore component.
 */
export interface DatastoreOutputs {
    /** S3 bucket name. */
    bucketName: pulumi.Output<string>;
    /** S3 bucket ARN. */
    bucketArn: pulumi.Output<string>;
    /** RDS endpoint (hostname:port). */
    rdsEndpoint: pulumi.Output<string>;
    /** RDS instance identifier. */
    rdsInstanceId: pulumi.Output<string>;
    /** IAM role ARN for workload identity. */
    roleArn: pulumi.Output<string>;
    /** IAM role name. */
    roleName: pulumi.Output<string>;
    /** Encrypted DB connection string (for secret injection into workloads). */
    dbConnectionString: pulumi.Output<string>;
}
```

**`src/datastore.ts`**
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

import { DatastoreArgs, DatastoreOutputs } from "./types";

/**
 * Datastore is a Pulumi ComponentResource that bundles:
 *   - S3 bucket (versioned, SSE, public-access blocked)
 *   - RDS PostgreSQL instance (deletion-protected, backed up)
 *   - IAM role (least-privilege, OIDC-trusted on prod)
 *
 * It is parameterized entirely by DatastoreArgs so that dev and prod
 * stacks can deploy independently with different sizing/security postures.
 */
export class Datastore extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly rdsEndpoint: pulumi.Output<string>;
    public readonly rdsInstanceId: pulumi.Output<string>;
    public readonly roleArn: pulumi.Output<string>;
    public readonly roleName: pulumi.Output<string>;
    public readonly dbConnectionString: pulumi.Output<string>;

    constructor(name: string, args: DatastoreArgs, opts?: pulumi.ComponentResourceOptions) {
        super("app:infra:Datastore", name, {}, opts);

        const {
            region,
            environment,
            rdsInstanceClass,
            rdsAllocatedStorage,
            rdsMultiAz,
            rdsStorageEncrypted,
            sseAlgorithm,
            kmsKeyArn,
            dbPassword,
            oidcProviderArn,
            oidcServiceAccount,
        } = args;

        // ─── Tags (common) ────────────────────────────────────────────────────
        const tags: { [key: string]: string } = {
            "Environment": environment,
            "ManagedBy": "pulumi",
            "Component": "datastore",
        };

        // ─── 1. S3 Bucket ────────────────────────────────────────────────────
        const bucket = new aws.s3.BucketV2(name, {
            bucket: `${name}-${environment}`,
            tags,
            // Versioning
            versioning: {
                enabled: true,
            },
            // Encryption
            serverSideEncryptionConfiguration: {
                rule: {
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: sseAlgorithm,
                        kmsMasterKeyId: sseAlgorithm === "aws:kms" ? kmsKeyArn : undefined,
                    },
                },
            },
            // Block all public access (acceptance criterion #1)
            publicAccessBlock: {
                blockPublicAcls: true,
                blockPublicPolicy: true,
                blockPublicPolicyIgnoreAcls: true,
                ignorePublicAcls: true,
            },
        }, { parent: this });

        this.bucketName = bucket.id;
        this.bucketArn = bucket.arn;

        // ─── 2. RDS PostgreSQL Instance ──────────────────────────────────────
        // KMS key for RDS encryption (required when storageEncrypted=true)
        const rdsKmsKey = rdsStorageEncrypted
            ? new aws.kms.Key(`${name}-rds-kms`, {
                description: `KMS key for RDS storage encryption (${environment})`,
                enableKeyRotation: true,
                tags,
            }, { parent: this })
            : undefined;

        const rds = new aws.rds.Instance(name, {
            identifier: `${name}-${environment}`,
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: rdsInstanceClass,
            allocatedStorage: rdsAllocatedStorage,
            dbName: "appdb",
            username: "app",
            password: dbPassword,  // from encrypted stack config
            multiAz: rdsMultiAz,
            storageEncrypted: rdsStorageEncrypted,
            kmsKeyId: rdsKmsKey?.arn,
            // Acceptance criterion #2: deletion protection + backup retention
            deletionProtection: true,
            backupRetentionPeriod: environment === "prod" ? 30 : 7,
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${environment}-final`,
            // Not publicly accessible
            publiclyAccessible: false,
            // Security group: only allow traffic from VPC CIDR (tightened in prod)
            vpcSecurityGroups: opts?.parent
                ? pulumi.all([
                    // In a full deployment this would reference the cluster SG.
                    // Here we create a dedicated SG scoped to the component.
                ]).apply(() => {
                    const sg = new aws.ec2.SecurityGroup(`${name}-rds-sg`, {
                        name: `${name}-rds-sg`,
                        vpcId: aws.ec2.getVpc({ defaultForRegion: true }).then(
                            vpc => vpc.id
                        ),
                        description: "Allow PostgreSQL from application subnets only",
                        tags,
                    }, { parent: this });

                    new aws.ec2.SecurityGroupRule(`${name}-rds-ingress`, {
                        securityGroupId: sg.id,
                        type: "ingress",
                        fromPort: 5432,
                        toPort: 5432,
                        protocol: "tcp",
                        // In a real deployment, reference the app subnet CIDR(s).
                        // Using 10.0.0.0/8 as a placeholder for VPC-internal.
                        cidrBlocks: ["10.0.0.0/8"],
                        description: "PostgreSQL from VPC-internal",
                    }, { parent: this });

                    return [sg.id];
                })
                : ["pulumi-managed"],
            tags,
        }, { parent: this });

        this.rdsEndpoint = rds.endpoint;
        this.rdsInstanceId = rds.id;

        // DB connection string (exposed as output; consumers should inject via secret manager)
        this.dbConnectionString = pulumi.interpolate`postgres://app:${dbPassword}@${rds.endpoint}/appdb`;

        // ─── 3. IAM Role (Service Account) ───────────────────────────────────

        // Trust policy: varies by environment
        //   dev  → allow any principal within the account (programmatic access)
        //   prod → OIDC trust for IRSA / workload identity
        const assumeRolePolicy = environment === "prod" && oidcProviderArn
            ? JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Effect: "Allow",
                        Principal: {
                            Federated: oidcProviderArn,
                        },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${new URL(oidcProviderArn).hostname}:sub`]: `system:serviceaccount:default:${oidcServiceAccount ?? "app-sa"}`,
                            },
                        },
                    },
                ],
            })
            : JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Effect: "Allow",
                        Principal: {
                            Service: "ec2.amazonaws.com",
                        },
                        Action: "sts:AssumeRole",
                    },
                ],
            });

        const role = new aws.iam.Role(`${name}-sa`, {
            name: `${name}-sa-${environment}`,
            assumeRolePolicy,
            maxSessionDuration: 3600,
            tags,
        }, { parent: this });

        this.roleName = role.name;
        this.roleArn = role.arn;

        // ─── Permission Policy (least privilege, no wildcards on prod) ──────
        const statements: any[] = [];

        // S3: scoped to this specific bucket
        statements.push({
            Effect: "Allow",
            Action: [
                "s3:GetObject",
                "s3:PutObject",
                "s3:ListBucket",
                "s3:GetBucketLocation",
            ],
            Resource: [
                bucket.arn,
                pulumi.interpolate`${bucket.arn}/*`,
            ],
        });

        if (environment === "prod") {
            // Prod: explicit, scoped actions only
            // (No wildcard actions per acceptance criterion #4)
            statements.push({
                Effect: "Allow",
                Action: [
                    "kms:Decrypt",
                    "kms:GenerateDataKey",
                ],
                Resource: kmsKeyArn ? [kmsKeyArn] : pulumi.output([]),
            });
        } else {
            // Dev: slightly broader for ease of use (still scoped to bucket)
            statements.push({
                Effect: "Allow",
                Action: [
                    "s3:DeleteObject",
                    "s3:RestoreObject",
                ],
                Resource: [
                    pulumi.interpolate`${bucket.arn}/*`,
                ],
            });
        }

        const policy = new aws.iam.Policy(`${name}-sa-policy`, {
            name: `${name}-sa-policy-${environment}`,
            policy: JSON.stringify({
                Version: "2012-10-17",
                Statement: statements,
            }),
            tags,
        }, { parent: this });

        new aws.iam.RolePolicyAttachment(`${name}-sa-attach`, {
            role: role.name,
            policyArn: policy.arn,
        }, { parent: this });

        // ─── Register outputs on the component ───────────────────────────────
        this.registerOutputs({
            bucketName: this.bucketName,
            bucketArn: this.bucketArn,
            rdsEndpoint: this.rdsEndpoint,
            rdsInstanceId: this.rdsInstanceId,
            roleArn: this.roleArn,
            roleName: this.roleName,
        });
    }
}
```

**`src/index.ts`**
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

import { Datastore } from "./datastore";
import { DatastoreArgs } from "./types";

// ─── Read stack config ────────────────────────────────────────────────────────
const config = new pulumi.Config("app");
const region = config.require("region");
const environment = config.require("environment");
const rdsInstanceClass = config.require("rdsInstanceClass");
const rdsAllocatedStorage = config.getNumber("rdsAllocatedStorage") ?? 20;
const rdsMultiAz = config.getBoolean("rdsMultiAz") ?? false;
const rdsStorageEncrypted = config.getBoolean("rdsStorageEncrypted") ?? false;
const sseAlgorithm = config.require("sseAlgorithm");
const kmsKeyArn = config.get("kmsKeyArn");
const dbPassword = config.requireSecret("dbPassword");
const oidcProviderArn = config.get("oidcProviderArn");
const oidcServiceAccount = config.get("oidcServiceAccount");

// ─── Set region on the provider ───────────────────────────────────────────────
aws.config.region = region;

// ─── Deploy the Datastore component ──────────────────────────────────────────
const datastore = new Datastore("primary", {
    region,
    environment,
    rdsInstanceClass,
    rdsAllocatedStorage,
    rdsMultiAz,
    rdsStorageEncrypted,
    sseAlgorithm,
    kmsKeyArn,
    dbPassword,
    oidcProviderArn,
    oidcServiceAccount,
});

// ─── Export outputs (visible via `pulumi stack output`) ──────────────────────
export const bucketName = datastore.bucketName;
export const bucketArn = datastore.bucketArn;
export const rdsEndpoint = datastore.rdsEndpoint;
export const rdsInstanceId = datastore.rdsInstanceId;
export const roleArn = datastore.roleArn;
export const roleName = datastore.roleName;
export const dbConnectionString = datastore.dbConnectionString;
```

